fn list_quizzes(conn: &Connection) -> Vec<Quiz> {
    let mut stmt = conn
        .prepare("SELECT id, title FROM quizzes ORDER BY id ASC")
        .unwrap();
    let rows = stmt
        .query_map([], |row| {
            Ok(Quiz {
                id: row.get(0)?,
                title: row.get(1)?,
            })
        })
        .unwrap();
    rows.filter_map(|r| r.ok()).collect()
}

fn get_quiz(conn: &Connection, id: i64) -> Option<Quiz> {
    conn.query_row("SELECT id, title FROM quizzes WHERE id=?1", params![id], |row| {
        Ok(Quiz {
            id: row.get(0)?,
            title: row.get(1)?,
        })
    })
    .optional()
    .unwrap()
}

fn count_questions(conn: &Connection, quiz_id: i64) -> (i64, i64) {
    let total: i64 = conn
        .query_row(
            "SELECT COUNT(*) FROM questions WHERE quiz_id=?1",
            params![quiz_id],
            |r| r.get(0),
        )
        .unwrap_or(0);
    let active: i64 = conn
        .query_row(
            "SELECT COUNT(*) FROM questions WHERE quiz_id=?1 AND active=1",
            params![quiz_id],
            |r| r.get(0),
        )
        .unwrap_or(0);
    (total, active)
}

fn list_questions(conn: &Connection, quiz_id: i64) -> Vec<Question> {
    let mut stmt = conn
        .prepare("SELECT id, quiz_id, body, active, position FROM questions WHERE quiz_id=?1 ORDER BY position ASC, id ASC")
        .unwrap();
    let rows = stmt
        .query_map(params![quiz_id], |row| {
            let active_int: i64 = row.get(3)?;
            Ok(Question {
                id: row.get(0)?,
                quiz_id: row.get(1)?,
                body: row.get(2)?,
                active: active_int != 0,
                position: row.get(4)?,
            })
        })
        .unwrap();
    rows.filter_map(|r| r.ok()).collect()
}

fn get_question(conn: &Connection, quiz_id: i64, qid: i64) -> Option<Question> {
    conn.query_row(
        "SELECT id, quiz_id, body, active, position FROM questions WHERE id=?1 AND quiz_id=?2",
        params![qid, quiz_id],
        |row| {
            let active_int: i64 = row.get(3)?;
            Ok(Question {
                id: row.get(0)?,
                quiz_id: row.get(1)?,
                body: row.get(2)?,
                active: active_int != 0,
                position: row.get(4)?,
            })
        },
    )
    .optional()
    .unwrap()
}

fn list_options(conn: &Connection, question_id: i64) -> Vec<OptionItem> {
    let mut stmt = conn
        .prepare("SELECT id, question_id, body, is_correct, position FROM options WHERE question_id=?1 ORDER BY position ASC, id ASC")
        .unwrap();
    let rows = stmt
        .query_map(params![question_id], |row| {
