fn counts_per_option(
    conn: &Connection,
    game_id: i64,
    question_id: i64,
) -> HashMap<i64, i64> {
    let mut map = HashMap::new();
    let mut stmt = match conn.prepare(
        "SELECT option_id, COUNT(*) FROM answers WHERE game_id=?1 AND question_id=?2 GROUP BY option_id",
    ) {
        Ok(s) => s,
        Err(_) => return map,
    };
    if let Ok(rows) = stmt.query_map(params![game_id, question_id], |row| {
        let oid: i64 = row.get(0)?;
        let c: i64 = row.get(1)?;
        Ok((oid, c))
    }) {
        for r in rows.flatten() {
            map.insert(r.0, r.1);
        }
    }
    map
}

fn get_player_by_token(conn: &Connection, game_id: i64, token: &str) -> Option<Player> {
    let t = token.trim().trim_matches('"');
    if t.is_empty() {
        return None;
    }
    // tokens are hex; ignore obviously wrong
    conn.query_row(
        "SELECT id, game_id, name, token FROM players WHERE game_id=?1 AND token=?2",
        params![game_id, t],
        |row| {
            Ok(Player {
                id: row.get(0)?,
                game_id: row.get(1)?,
                name: row.get(2)?,
                token: row.get(3)?,
            })
        },
    )
    .optional()
    .unwrap()
}

fn find_player_for_game(
    conn: &Connection,
    game: &Game,
    headers: &HeaderMap,
    query_token: Option<&str>,
) -> Option<Player> {
    if let Some(qt) = query_token {
        let q = qt.trim();
        if !q.is_empty() {
            if let Some(p) = get_player_by_token(conn, game.id, q) {
                return Some(p);
            }
            // try decoded
            let dec = percent_decode(q);
            if dec != q {
                if let Some(p) = get_player_by_token(conn, game.id, &dec) {
                    return Some(p);
                }
            }
        }
    }
    if let Some(v) = headers.get("x-player-token") {
        if let Ok(s) = v.to_str() {
            let s = s.trim();
            if !s.is_empty() {
                if let Some(p) = get_player_by_token(conn, game.id, s) {
                    return Some(p);
                }
            }
        }
    }
    let cookies = parse_cookies(headers);
    let code = &game.code;
    for key in [
        format!("quizzy_{}", code),
        format!("qz_{}", code),
        "quizzy_player".to_string(),
        "player_token".to_string(),
        "player".to_string(),
    ] {
        if let Some(v) = cookies.get(&key) {
            let vv = v.trim().trim_matches('"');
            if let Some(p) = get_player_by_token(conn, game.id, vv) {
                return Some(p);
            }
            let dec = percent_decode(vv);
            if dec != vv {
                if let Some(p) = get_player_by_token(conn, game.id, &dec) {
                    return Some(p);
                }
            }
        }
    }
    for v in cookies.values() {
        if v.len() > 200 {
            continue;
        }
        let vv = v.trim().trim_matches('"');
        if let Some(p) = get_player_by_token(conn, game.id, vv) {
            return Some(p);
        }
        let dec = percent_decode(vv);
        if dec != vv {
            if let Some(p) = get_player_by_token(conn, game.id, &dec) {
                return Some(p);
            }
        }
    }
    None
}

