async fn create_game_handler(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> impl IntoResponse {
    let conn = db_connect(&state).unwrap();
    let Some(_quiz) = get_quiz(&conn, id) else {
        return (StatusCode::NOT_FOUND, Html(admin_layout("Not found", "<h1>Quiz not found</h1>"))).into_response();
    };
    // generate unique code
    let code = generate_game_code(&conn);
    conn.execute(
        "INSERT INTO games (quiz_id, code, status, current_question_id) VALUES (?1, ?2, 'lobby', NULL)",
        params![id, code],
    )
    .unwrap();
    Redirect::to(&format!("/moderate/games/{}", code)).into_response()
}

